// Frozen legacy observation input builder from LIBRA 2.3.76. Tests exercise the current compatibility consumer, not a live producer.
module.exports = "const bindStateObservationCas = (observationValue, headValue, registryValue) => {\n      const observation = clone(observationValue);\n      const head = asObject(headValue);\n      for (const patch of asArray(observation?.patches)) {\n        let current = null;\n        let currentState = {};\n        if (observation.domain === 'relationship') {\n          const subject = statePipelineRegistryEntity(registryValue, patch.subjectId, 'person');\n          const target = statePipelineRegistryEntity(registryValue, patch.targetId, 'person');\n          const relationId = subject && target && CONTINUITY_STATE_RELATION_DIMENSIONS.includes(patch.dimension)\n            ? `cs_rel_${stableHash(`${subject.id}>${target.id}:${patch.dimension}`)}` : '';\n          current = relationId ? asArray(head.relationships).find(row => row?.id === relationId) || null : null;\n          currentState = asObject(current?.state);\n        } else if (observation.domain === 'narrative') {\n          current = normalizeCurrentNarrativeState(head.narrative);\n          currentState = asObject(current);\n        } else {\n          const collection = asArray(head[STATE_PIPELINE_DOMAIN_HEAD_KEYS[observation.domain]]);\n          current = collection.find(row => row?.id === patch.entityId) || null;\n          currentState = asObject(current?.state);\n        }\n        patch.expectedRecordHash = digest(statePipelineStableObject(current || null));\n        patch.expectedFieldHashes = Object.fromEntries(Array.from(new Set([...Object.keys(asObject(patch.set)), ...asArray(patch.clear)]))\n          .map(field => [field, digest(statePipelineSemanticValue(field, currentState[field]))]));\n      }\n      return observation;\n    };";
